replace_once('src/backend/polaris/cells/roles/adapters/internal/director/deterministic_repairs/generic_repairs.py', 'def _apply_deterministic_go_module_import_repair(\n    adapter: Any,\n    *,\n    task_id: str,\n) -> list[dict[str, Any]]:\n    """Repair Go import paths that reference a wrong module prefix."""\n    workspace = Path(getattr(adapter, "workspace", "") or "")\n    if not workspace.is_dir():\n        return []\n    go_files = list(workspace.rglob("*.go"))\n    if not (workspace / "go.mod").is_file() or not go_files:\n        return []\n    repairs = repair_go_module_imports(workspace)\n    if not repairs:\n        return []\n    results: list[dict[str, Any]] = []\n    for record in repairs:\n        results.append(\n            {\n                "tool": "write_file",\n                "tool_name": "write_file",\n                "success": True,\n                "result": {\n                    "ok": True,\n                    "source_tool": "deterministic_go_module_import_repair",\n                    "file": record["file"],\n                    "before": record["before"],\n                    "after": record["after"],\n                },\n            }\n        )\n    return results\n', 'def _apply_deterministic_go_module_import_repair(\n    adapter: Any,\n    *,\n    task_id: str,\n    artifact_quality_errors: list[str],\n) -> list[dict[str, Any]]:\n    """Execute conservative Go import repair plans through Director tools."""\n\n    workspace_path = Path(str(getattr(adapter, "workspace", "") or "")).resolve()\n    if not workspace_path.is_dir():\n        return []\n    plans = plan_go_module_import_repairs(\n        workspace_path,\n        artifact_quality_errors=artifact_quality_errors,\n    )\n    if not plans:\n        return []\n\n    message_bus = getattr(getattr(adapter, "_execution", None), "_message_bus", None)\n    executor = DirectorToolExecutor(\n        str(workspace_path),\n        message_bus=message_bus,\n        worker_id="director",\n    )\n    results: list[dict[str, Any]] = []\n    for plan in plans:\n        write_result = executor.execute_tool(\n            "write_file",\n            {"file": plan.file, "content": plan.content},\n            task_id=task_id,\n        )\n        success = bool(write_result.get("ok"))\n        evidence: dict[str, Any] = {\n            **write_result,\n            "ok": success,\n            "source_tool": "deterministic_go_module_import_repair",\n            "file": plan.file,\n            "replacements": [\n                {"before": replacement.before, "after": replacement.after}\n                for replacement in plan.replacements\n            ],\n        }\n        item: dict[str, Any] = {\n            "tool": "write_file",\n            "tool_name": "write_file",\n            "success": success,\n            "result": evidence,\n        }\n        if not success:\n            item["error"] = str(write_result.get("error") or "Go import repair write failed")\n        results.append(item)\n        if success:\n            with contextlib.suppress(OSError, RuntimeError, TypeError, ValueError):\n                adapter._update_task_progress(task_id, "executing", current_file=plan.file)\n    return results\n')

